% function compile_isotropic_remeshing
%     mex -v -O isotropic_remeshing.cpp -I/usr/include:/usr/local/include -L/usr/lib:/usr/local/lib -lgmp -lboost_thread
% end

% NPM: as of 2026 the following works on D'Arcy

function compile_isotropic_remeshing
    mex('-v', '-O', ...
        'CXXFLAGS=$CXXFLAGS -std=c++14 -frounding-math', ...
        'isotropic_remeshing.cpp', ...
        '-lgmp', ...
        '-lmpfr', ...
        '-lboost_thread');
end
